mkdir -p site/blog
for f in index.html about.html 'blog/first post.html' style.css; do
  printf '<p>%s</p>\n' "$f" > "site/$f"
done

expected_conf=$(cat <<'EOF'
# generated by vhost for example.org
server {
    listen 8080;
    server_name example.org;
    root site;
    location / {
        try_files $uri $uri/ =404;
    }
    location /api/ {
        proxy_pass http://127.0.0.1:8081;
        proxy_set_header Host $host;
    }
}
EOF
)

out=$(bash solution.sh example.org:8080 site 2> err.txt)
assert_eq "$?" "0" "exit status for the example site"
assert_eq "$out" "page ./about.html
page ./blog/first post.html
page ./index.html
wrote example.org.conf for 3 pages" "the pages and the summary printed for the example site"
assert_eq "$(cat err.txt)" "" "nothing on standard error for the example site"
[[ -f example.org.conf ]] || fail "HOST.conf is written in the current directory"
assert_eq "$(cat example.org.conf)" "$expected_conf" "the server block written to example.org.conf"
